// Times arrow::internal::CountSetBits on random bitmaps (sizes as in the PR's
// benchmark) and writes counts, checked against a naive bit loop, to a file.
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <random>
#include <vector>
#include "arrow/util/bitmap_ops.h"

static int64_t Naive(const uint8_t* d, int64_t off, int64_t n) {
  int64_t c = 0;
  for (int64_t i = off; i < off + n; ++i) c += (d[i >> 3] >> (i & 7)) & 1;
  return c;
}

int main(int argc, char** argv) {
  const char* out = argc > 1 ? argv[1] : "counts.txt";
  std::mt19937_64 rng(42);
  std::vector<uint8_t> buf(1 << 17);
  for (auto& b : buf) b = static_cast<uint8_t>(rng());
  FILE* f = fopen(out, "w");
  int bad = 0;
  // correctness: many offsets/lengths
  for (int64_t off = 0; off < 70; ++off)
    for (int64_t n : {0, 1, 7, 63, 64, 65, 255, 256, 257, 1000, 4096, 8191, 100003}) {
      int64_t a = arrow::internal::CountSetBits(buf.data(), off, n), b = Naive(buf.data(), off, n);
      if (a != b) ++bad;
      fprintf(f, "%ld %ld %ld\n", (long)off, (long)n, (long)a);
    }
  fprintf(f, "mismatches_vs_naive %d\n", bad);
  fclose(f);
  // timing
  int64_t sink = 0;
  auto t0 = std::chrono::steady_clock::now();
  for (int64_t nbytes : {16, 1024, 1 << 17}) {
    int64_t iters = (1 << 27) / nbytes * 4;
    for (int64_t i = 0; i < iters; ++i) {
      sink += arrow::internal::CountSetBits(buf.data(), 0, nbytes * 8);
      asm volatile("" : "+r"(sink) : : "memory");
    }
  }
  double s = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
  printf("PERFPROOF {\"value\": %.9f}\n", s);
  return sink == 0 ? 1 : 0;
}
EOF
